contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address caller, address recipient) public payable {
        require(address(this).balance >= 0);
        require(caller != address(this), "test contract is the owner");

        uint256 beforeBal = address(c).balance;
        bool reverted;

        // Setup: make sure c has some balance by sending ether to it.
        // (fallback accepts ether)
        (bool ok, ) = address(c).call{value: 0}("");
        require(ok, "setup call failed");

        beforeBal = address(c).balance;

        // The deciding call: caller (not owner) attempts withdrawAll.
        // Since caller != address(this) and owner is address(this), this must revert.
        try c.withdrawAll(recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterBal = address(c).balance;

        assert(reverted && afterBal == beforeBal);
    }

    receive() external payable {}
}

